import json, urllib.request

def gql(query, variables=None):
    req = urllib.request.Request(
        "https://api.linear.app/graphql",
        data=json.dumps({"query": query, "variables": variables or {}}).encode(),
        headers={"Authorization": "***", "Content-Type": "application/json"})
    return json.load(urllib.request.urlopen(req))

q = '''query($ids: [ID!]) {
  cycles(filter: { id: { in: $ids } }) {
    nodes {
      id name number startsAt endsAt team { key name }
      issues(first: 100) { nodes { id identifier title priority assignee { name } state { name } } }
    }
  }
}'''
r = gql(q, {"ids": ["93d36c82-7548-43bb-8e58-45056be0fe61", "9de25ce9-6da6-4fcd-be87-c3894e29f806"]})
for c in r["data"]["cycles"]["nodes"]:
    print(c["name"], c["team"]["key"], c["startsAt"], c["endsAt"], c["id"])
    for i in c["issues"]["nodes"]:
        print("   ", i["identifier"], "|", i["title"], "|", i["priority"], "|", i["assignee"]["name"], "|", i["state"]["name"])
EOF

